// axi4_lite_regs
// Four 32-bit read/write registers behind an AXI4-Lite subordinate port.
// Implements microarchitecture.md:
//   * READY is a function of state only (no combinational VALID->READY path).
//   * AW and W are captured in holding registers; the write fires on the edge
//     that completes the pair, so AW-first, W-first and same-cycle need no
//     special cases.
//   * One outstanding transaction per direction; BVALID/RVALID are registered
//     (1-cycle latency) and their payloads cannot change while they wait.
//   * Unmapped (misaligned or out-of-range) accesses complete with SLVERR,
//     change no register, and reads return zero.
module axi4_lite_regs #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,

    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,

    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,

    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,

    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,

    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

    localparam integer STRB_WIDTH  = DATA_WIDTH / 8;
    localparam [1:0]   RESP_OKAY   = 2'b00;
    localparam [1:0]   RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // Helper functions
    // ------------------------------------------------------------------

    // An address is mapped when it is word aligned and within 0x0..0xC.
    function is_mapped;
        input [ADDR_WIDTH-1:0] addr;
        begin
            is_mapped = (addr[1:0] == 2'b00) &&
                        ((addr >> 4) == {ADDR_WIDTH{1'b0}});
        end
    endfunction

    // Copy the bytes of new_value selected by byte_mask, keep the others.
    function [DATA_WIDTH-1:0] merge;
        input [DATA_WIDTH-1:0] old_value;
        input [DATA_WIDTH-1:0] new_value;
        input [DATA_WIDTH-1:0] byte_mask;
        begin
            merge = (old_value & ~byte_mask) | (new_value & byte_mask);
        end
    endfunction

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------

    // Write side control
    reg                   aw_held;
    reg                   w_held;
    reg                   bvalid_q;
    reg  [1:0]            bresp_q;

    // Write holding registers (datapath, not reset)
    reg  [ADDR_WIDTH-1:0] aw_addr_q;
    reg  [DATA_WIDTH-1:0] w_data_q;
    reg  [STRB_WIDTH-1:0] w_strb_q;

    // Read side
    reg                   rvalid_q;
    reg  [1:0]            rresp_q;
    reg  [DATA_WIDTH-1:0] rdata_q;

    // Register file
    reg  [DATA_WIDTH-1:0] reg0;
    reg  [DATA_WIDTH-1:0] reg1;
    reg  [DATA_WIDTH-1:0] reg2;
    reg  [DATA_WIDTH-1:0] reg3;

    // ------------------------------------------------------------------
    // Handshakes (READY from state only)
    // ------------------------------------------------------------------

    assign s_axil_awready = !aw_held && !bvalid_q;
    assign s_axil_wready  = !w_held  && !bvalid_q;
    assign s_axil_arready = !rvalid_q;

    wire aw_hs = s_axil_awvalid && s_axil_awready;
    wire w_hs  = s_axil_wvalid  && s_axil_wready;
    wire ar_hs = s_axil_arvalid && s_axil_arready;

    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [DATA_WIDTH-1:0] wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [STRB_WIDTH-1:0] wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;
    wire                  wr_ok   = is_mapped(wr_addr);
    wire                  rd_ok   = is_mapped(s_axil_araddr);

    // Byte strobes expanded to a bit mask
    wire [DATA_WIDTH-1:0] wr_mask;
    genvar gi;
    generate
        for (gi = 0; gi < STRB_WIDTH; gi = gi + 1) begin : g_strb_mask
            assign wr_mask[8*gi +: 8] = {8{wr_strb[gi]}};
        end
    endgenerate

    // Read data selection (register index is addr[3:2])
    reg [DATA_WIDTH-1:0] rd_sel;
    always @(*) begin
        case (s_axil_araddr[3:2])
            2'd0:    rd_sel = reg0;
            2'd1:    rd_sel = reg1;
            2'd2:    rd_sel = reg2;
            default: rd_sel = reg3;
        endcase
    end

    // ------------------------------------------------------------------
    // Holding registers (datapath, no reset; only used when *_held is set)
    // ------------------------------------------------------------------

    always @(posedge aclk) begin
        if (aw_hs) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    // ------------------------------------------------------------------
    // Control, responses and register file (synchronous active-low reset)
    // ------------------------------------------------------------------

    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held  <= 1'b0;
            w_held   <= 1'b0;
            bvalid_q <= 1'b0;
            bresp_q  <= RESP_OKAY;
            rvalid_q <= 1'b0;
            rresp_q  <= RESP_OKAY;
            rdata_q  <= {DATA_WIDTH{1'b0}};
            reg0     <= {DATA_WIDTH{1'b0}};
            reg1     <= {DATA_WIDTH{1'b0}};
            reg2     <= {DATA_WIDTH{1'b0}};
            reg3     <= {DATA_WIDTH{1'b0}};
        end else begin
            // ---------------- write channel ----------------
            if (do_write) begin
                aw_held  <= 1'b0;
                w_held   <= 1'b0;
                bvalid_q <= 1'b1;
                if (wr_ok) begin
                    bresp_q <= RESP_OKAY;
                    case (wr_addr[3:2])
                        2'd0:    reg0 <= merge(reg0, wr_data, wr_mask);
                        2'd1:    reg1 <= merge(reg1, wr_data, wr_mask);
                        2'd2:    reg2 <= merge(reg2, wr_data, wr_mask);
                        default: reg3 <= merge(reg3, wr_data, wr_mask);
                    endcase
                end else begin
                    bresp_q <= RESP_SLVERR;
                end
            end else begin
                if (aw_hs) begin
                    aw_held <= 1'b1;
                end
                if (w_hs) begin
                    w_held <= 1'b1;
                end
                if (bvalid_q && s_axil_bready) begin
                    bvalid_q <= 1'b0;
                end
            end

            // ---------------- read channel ----------------
            if (ar_hs) begin
                rvalid_q <= 1'b1;
                if (rd_ok) begin
                    rresp_q <= RESP_OKAY;
                    rdata_q <= rd_sel;
                end else begin
                    rresp_q <= RESP_SLVERR;
                    rdata_q <= {DATA_WIDTH{1'b0}};
                end
            end else if (rvalid_q && s_axil_rready) begin
                rvalid_q <= 1'b0;
            end
        end
    end

    assign s_axil_bvalid = bvalid_q;
    assign s_axil_bresp  = bresp_q;
    assign s_axil_rvalid = rvalid_q;
    assign s_axil_rresp  = rresp_q;
    assign s_axil_rdata  = rdata_q;

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (microarchitecture.md section 7).
    // Not proven in this submission; no SymbiYosys job file accompanies it.
    // ------------------------------------------------------------------
    reg f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    // Start in reset; manager keeps VALID low during reset.
    always @(*) begin
        if (!f_past_valid) assume(!aresetn);
        if (!aresetn) begin
            assume(!s_axil_awvalid);
            assume(!s_axil_wvalid);
            assume(!s_axil_arvalid);
        end
    end

    // Manager holds VALID and payload until READY.
    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            if ($past(s_axil_awvalid && !s_axil_awready)) begin
                assume(s_axil_awvalid);
                assume(s_axil_awaddr == $past(s_axil_awaddr));
            end
            if ($past(s_axil_wvalid && !s_axil_wready)) begin
                assume(s_axil_wvalid);
                assume(s_axil_wdata == $past(s_axil_wdata));
                assume(s_axil_wstrb == $past(s_axil_wstrb));
            end
            if ($past(s_axil_arvalid && !s_axil_arready)) begin
                assume(s_axil_arvalid);
                assume(s_axil_araddr == $past(s_axil_araddr));
            end
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid) begin
            if ($past(!aresetn)) begin
                // Responses low and no half-write after reset.
                assert(!bvalid_q);
                assert(!rvalid_q);
                assert(!aw_held);
                assert(!w_held);
            end else begin
                // At most one write request open.
                assert(!(aw_held && w_held));
                assert(!(bvalid_q && (aw_held || w_held)));
                // Responses hold, with stable payload, until taken.
                if ($past(bvalid_q && !s_axil_bready)) begin
                    assert(bvalid_q);
                    assert(bresp_q == $past(bresp_q));
                end
                if ($past(rvalid_q && !s_axil_rready)) begin
                    assert(rvalid_q);
                    assert(rresp_q == $past(rresp_q));
                    assert(rdata_q == $past(rdata_q));
                end
                // A response appears one cycle after an accepted request ...
                if ($past(do_write)) begin
                    assert(bvalid_q);
                    assert(bresp_q == ($past(wr_ok) ? RESP_OKAY : RESP_SLVERR));
                end
                if ($past(ar_hs)) begin
                    assert(rvalid_q);
                    assert(rresp_q == ($past(rd_ok) ? RESP_OKAY : RESP_SLVERR));
                end
                // ... and never without one.
                if (!$past(bvalid_q) && !$past(do_write)) assert(!bvalid_q);
                if (!$past(rvalid_q) && !$past(ar_hs))    assert(!rvalid_q);
            end
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
