// Directed self-checking testbench for axi4_lite_regs.
// Inputs are driven just after the falling edge; handshakes and responses are
// sampled 1 ns later, well before the next rising edge, so there is no race.
module axi4_lite_regs_tb;

    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    reg         aclk    = 1'b0;
    reg         aresetn = 1'b0;

    reg  [3:0]  s_axil_awaddr  = 4'h0;
    reg         s_axil_awvalid = 1'b0;
    wire        s_axil_awready;
    reg  [31:0] s_axil_wdata   = 32'h0;
    reg  [3:0]  s_axil_wstrb   = 4'h0;
    reg         s_axil_wvalid  = 1'b0;
    wire        s_axil_wready;
    wire [1:0]  s_axil_bresp;
    wire        s_axil_bvalid;
    reg         s_axil_bready  = 1'b0;
    reg  [3:0]  s_axil_araddr  = 4'h0;
    reg         s_axil_arvalid = 1'b0;
    wire        s_axil_arready;
    wire [31:0] s_axil_rdata;
    wire [1:0]  s_axil_rresp;
    wire        s_axil_rvalid;
    reg         s_axil_rready  = 1'b0;

    integer        passed = 0;
    integer        failed = 0;
    integer        rc;
    reg [8*64-1:0] nonce;

    reg [3:0]      a;
    reg [31:0]     d;

    axi4_lite_regs #(
        .ADDR_WIDTH (4),
        .DATA_WIDTH (32)
    ) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (s_axil_awaddr),
        .s_axil_awvalid (s_axil_awvalid),
        .s_axil_awready (s_axil_awready),
        .s_axil_wdata   (s_axil_wdata),
        .s_axil_wstrb   (s_axil_wstrb),
        .s_axil_wvalid  (s_axil_wvalid),
        .s_axil_wready  (s_axil_wready),
        .s_axil_bresp   (s_axil_bresp),
        .s_axil_bvalid  (s_axil_bvalid),
        .s_axil_bready  (s_axil_bready),
        .s_axil_araddr  (s_axil_araddr),
        .s_axil_arvalid (s_axil_arvalid),
        .s_axil_arready (s_axil_arready),
        .s_axil_rdata   (s_axil_rdata),
        .s_axil_rresp   (s_axil_rresp),
        .s_axil_rvalid  (s_axil_rvalid),
        .s_axil_rready  (s_axil_rready)
    );

    always #5 aclk = ~aclk;

    task ok;
        begin
            passed = passed + 1;
        end
    endtask

    task bad;
        begin
            failed = failed + 1;
        end
    endtask

    // ------------------------------------------------------------------
    // One write. AW is presented after aw_dly cycles, W after w_dly cycles,
    // BREADY is raised after BVALID has been seen b_dly times.
    // ------------------------------------------------------------------
    task automatic axi_write(
        input [3:0]   addr,
        input [31:0]  data,
        input [3:0]   strb,
        input integer aw_dly,
        input integer w_dly,
        input integer b_dly,
        input [1:0]   exp_resp
    );
        integer   cyc;
        integer   done_edge;
        integer   lat;
        integer   bv_seen;
        reg       aw_done;
        reg       w_done;
        reg       b_done;
        reg [1:0] resp_seen;
        begin
            aw_done   = 1'b0;
            w_done    = 1'b0;
            b_done    = 1'b0;
            cyc       = 0;
            done_edge = -1;
            lat       = 0;
            bv_seen   = 0;
            resp_seen = 2'b00;
            while (!b_done && cyc < 64) begin
                @(negedge aclk);
                s_axil_awvalid = !aw_done && (cyc >= aw_dly);
                s_axil_awaddr  = addr;
                s_axil_wvalid  = !w_done && (cyc >= w_dly);
                s_axil_wdata   = data;
                s_axil_wstrb   = strb;
                s_axil_bready  = (bv_seen >= b_dly);
                #1;
                if (cyc == 0) begin
                    if (s_axil_awready && s_axil_wready) ok;
                    else begin
                        bad;
                        $error("write 0x%0h: AWREADY/WREADY not high at start (back-to-back)", addr);
                    end
                end
                if (s_axil_bvalid) begin
                    if (!(aw_done && w_done)) begin
                        bad;
                        $error("write 0x%0h: BVALID high before AW and W were both accepted", addr);
                    end else if (bv_seen == 0) begin
                        lat = cyc - done_edge;
                        if (lat >= 1 && lat <= 2) ok;
                        else begin
                            bad;
                            $error("write 0x%0h: latency %0d cycles, bound is 2", addr, lat);
                        end
                        resp_seen = s_axil_bresp;
                        if (s_axil_bresp == exp_resp) ok;
                        else begin
                            bad;
                            $error("write 0x%0h: BRESP %0b, expected %0b", addr, s_axil_bresp, exp_resp);
                        end
                    end else begin
                        if (s_axil_bresp == resp_seen) ok;
                        else begin
                            bad;
                            $error("write 0x%0h: BRESP changed while BVALID waited", addr);
                        end
                    end
                    if (s_axil_bready) b_done = 1'b1;
                    bv_seen = bv_seen + 1;
                end
                if (s_axil_awvalid && s_axil_awready) aw_done = 1'b1;
                if (s_axil_wvalid && s_axil_wready)   w_done  = 1'b1;
                if (aw_done && w_done && done_edge < 0) done_edge = cyc;
                cyc = cyc + 1;
            end
            if (b_done) ok;
            else begin
                bad;
                $error("write 0x%0h: timed out waiting for the write response", addr);
            end
        end
    endtask

    // ------------------------------------------------------------------
    // One read. AR is presented after ar_dly cycles, RREADY is raised after
    // RVALID has been seen r_dly times.
    // ------------------------------------------------------------------
    task automatic axi_read(
        input [3:0]   addr,
        input integer ar_dly,
        input integer r_dly,
        input [31:0]  exp_data,
        input [1:0]   exp_resp
    );
        integer    cyc;
        integer    done_edge;
        integer    lat;
        integer    rv_seen;
        reg        ar_done;
        reg        r_done;
        reg [1:0]  resp_seen;
        reg [31:0] data_seen;
        begin
            ar_done   = 1'b0;
            r_done    = 1'b0;
            cyc       = 0;
            done_edge = -1;
            lat       = 0;
            rv_seen   = 0;
            resp_seen = 2'b00;
            data_seen = 32'h0;
            while (!r_done && cyc < 64) begin
                @(negedge aclk);
                s_axil_arvalid = !ar_done && (cyc >= ar_dly);
                s_axil_araddr  = addr;
                s_axil_rready  = (rv_seen >= r_dly);
                #1;
                if (cyc == 0) begin
                    if (s_axil_arready) ok;
                    else begin
                        bad;
                        $error("read 0x%0h: ARREADY not high at start (back-to-back)", addr);
                    end
                end
                if (s_axil_rvalid) begin
                    if (!ar_done) begin
                        bad;
                        $error("read 0x%0h: RVALID high before AR was accepted", addr);
                    end else if (rv_seen == 0) begin
                        lat = cyc - done_edge;
                        if (lat >= 1 && lat <= 2) ok;
                        else begin
                            bad;
                            $error("read 0x%0h: latency %0d cycles, bound is 2", addr, lat);
                        end
                        resp_seen = s_axil_rresp;
                        data_seen = s_axil_rdata;
                        if (s_axil_rresp == exp_resp) ok;
                        else begin
                            bad;
                            $error("read 0x%0h: RRESP %0b, expected %0b", addr, s_axil_rresp, exp_resp);
                        end
                        if (s_axil_rdata == exp_data) ok;
                        else begin
                            bad;
                            $error("read 0x%0h: RDATA 0x%08h, expected 0x%08h", addr, s_axil_rdata, exp_data);
                        end
                    end else begin
                        if (s_axil_rresp == resp_seen && s_axil_rdata == data_seen) ok;
                        else begin
                            bad;
                            $error("read 0x%0h: RRESP/RDATA changed while RVALID waited", addr);
                        end
                    end
                    if (s_axil_rready) r_done = 1'b1;
                    rv_seen = rv_seen + 1;
                end
                if (s_axil_arvalid && s_axil_arready) ar_done = 1'b1;
                if (ar_done && done_edge < 0) done_edge = cyc;
                cyc = cyc + 1;
            end
            if (r_done) ok;
            else begin
                bad;
                $error("read 0x%0h: timed out waiting for read data", addr);
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        nonce = {8*64{1'b0}};
        rc = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (rc == 0) $display("note: no nirmaan_nonce plusarg given");

        // ---- 1. Reset ----
        aresetn = 1'b0;
        repeat (3) @(negedge aclk);
        #1;
        if (!s_axil_bvalid && !s_axil_rvalid) ok;
        else begin bad; $error("reset: BVALID/RVALID not low during reset"); end
        aresetn = 1'b1;
        if (s_axil_awready && s_axil_wready && s_axil_arready) ok;
        else begin bad; $error("reset: READY signals not high after reset"); end

        // Reset values
        axi_read(4'h0, 0, 0, 32'h0000_0000, OKAY);
        axi_read(4'h4, 0, 0, 32'h0000_0000, OKAY);
        axi_read(4'h8, 0, 0, 32'h0000_0000, OKAY);
        axi_read(4'hC, 0, 0, 32'h0000_0000, OKAY);

        // ---- 2. Write then read every register ----
        axi_write(4'h0, 32'h0123_4567, 4'hF, 0, 0, 0, OKAY);
        axi_write(4'h4, 32'h89AB_CDEF, 4'hF, 0, 0, 0, OKAY);
        axi_write(4'h8, 32'hDEAD_BEEF, 4'hF, 0, 0, 0, OKAY);
        axi_write(4'hC, 32'h5A5A_A5A5, 4'hF, 0, 0, 0, OKAY);
        axi_read(4'h0, 0, 0, 32'h0123_4567, OKAY);
        axi_read(4'h4, 0, 0, 32'h89AB_CDEF, OKAY);
        axi_read(4'h8, 0, 0, 32'hDEAD_BEEF, OKAY);
        axi_read(4'hC, 0, 0, 32'h5A5A_A5A5, OKAY);

        // ---- 3. wstrb partial writes (REG1) ----
        axi_write(4'h4, 32'h1122_3344, 4'hF, 0, 0, 0, OKAY);
        axi_read(4'h4, 0, 0, 32'h1122_3344, OKAY);
        axi_write(4'h4, 32'hAABB_CCDD, 4'b0101, 0, 0, 0, OKAY);
        axi_read(4'h4, 0, 0, 32'h11BB_33DD, OKAY);
        axi_write(4'h4, 32'h9900_0000, 4'b1000, 0, 0, 0, OKAY);
        axi_read(4'h4, 0, 0, 32'h99BB_33DD, OKAY);
        axi_write(4'h4, 32'h0000_EE00, 4'b0010, 0, 0, 0, OKAY);
        axi_read(4'h4, 0, 0, 32'h99BB_EEDD, OKAY);
        axi_write(4'h4, 32'hFFFF_FFFF, 4'b0000, 0, 0, 0, OKAY);   // no bytes enabled
        axi_read(4'h4, 0, 0, 32'h99BB_EEDD, OKAY);

        // ---- 4. AW/W ordering (REG2, REG3) ----
        axi_write(4'h8, 32'hA0A0_A0A0, 4'hF, 0, 3, 0, OKAY);   // AW before W
        axi_read(4'h8, 0, 0, 32'hA0A0_A0A0, OKAY);
        axi_write(4'h8, 32'hB1B1_B1B1, 4'hF, 2, 0, 0, OKAY);   // W before AW
        axi_read(4'h8, 0, 0, 32'hB1B1_B1B1, OKAY);
        axi_write(4'h8, 32'hC2C2_C2C2, 4'hF, 1, 1, 0, OKAY);   // together, after a gap
        axi_read(4'h8, 0, 0, 32'hC2C2_C2C2, OKAY);
        axi_write(4'hC, 32'h0F0F_0F0F, 4'hF, 0, 1, 0, OKAY);   // AW one cycle ahead
        axi_read(4'hC, 0, 0, 32'h0F0F_0F0F, OKAY);
        axi_write(4'hC, 32'hF0F0_F0F0, 4'hF, 1, 0, 0, OKAY);   // W one cycle ahead
        axi_read(4'hC, 0, 0, 32'hF0F0_F0F0, OKAY);

        // ---- 5. B and R backpressure ----
        axi_write(4'h0, 32'h1357_9BDF, 4'hF, 0, 0, 3, OKAY);
        axi_read(4'h0, 0, 4, 32'h1357_9BDF, OKAY);
        axi_write(4'h6, 32'h1111_1111, 4'hF, 0, 2, 2, SLVERR);
        axi_read(4'h6, 1, 2, 32'h0000_0000, SLVERR);

        // ---- 6. Back-to-back transactions ----
        a = 4'h0;
        d = 32'h1000_0001;
        repeat (4) begin
            axi_write(a, d, 4'hF, 0, 0, 0, OKAY);
            a = a + 4'h4;
            d = d + 32'h0101_0101;
        end
        a = 4'h0;
        d = 32'h1000_0001;
        repeat (4) begin
            axi_read(a, 0, 0, d, OKAY);
            a = a + 4'h4;
            d = d + 32'h0101_0101;
        end

        // ---- 7. SLVERR policy ----
        axi_write(4'h5, 32'hFFFF_FFFF, 4'hF, 0, 0, 0, SLVERR);
        axi_write(4'hE, 32'hFFFF_FFFF, 4'hF, 0, 0, 0, SLVERR);
        axi_write(4'h1, 32'hFFFF_FFFF, 4'hF, 0, 0, 0, SLVERR);
        axi_write(4'h3, 32'hFFFF_FFFF, 4'hF, 1, 0, 0, SLVERR);
        axi_read(4'hE, 0, 0, 32'h0000_0000, SLVERR);
        axi_read(4'h5, 0, 0, 32'h0000_0000, SLVERR);
        axi_read(4'h2, 0, 0, 32'h0000_0000, SLVERR);
        // No register changed
        a = 4'h0;
        d = 32'h1000_0001;
        repeat (4) begin
            axi_read(a, 0, 0, d, OKAY);
            a = a + 4'h4;
            d = d + 32'h0101_0101;
        end

        // ---- 8. Reset discards a half-accepted write ----
        @(negedge aclk);
        s_axil_awvalid = 1'b1;
        s_axil_awaddr  = 4'h8;
        s_axil_wvalid  = 1'b0;
        s_axil_bready  = 1'b0;
        s_axil_arvalid = 1'b0;
        s_axil_rready  = 1'b0;
        #1;
        if (s_axil_awready) ok;
        else begin bad; $error("half-write: AWREADY not high"); end
        @(negedge aclk);                 // AW accepted on the rising edge before this
        s_axil_awvalid = 1'b0;
        #1;
        if (!s_axil_awready && !s_axil_bvalid) ok;
        else begin bad; $error("half-write: AW not held while waiting for W"); end
        aresetn = 1'b0;
        repeat (2) @(negedge aclk);
        #1;
        if (!s_axil_bvalid && !s_axil_rvalid &&
            s_axil_awready && s_axil_wready && s_axil_arready) ok;
        else begin bad; $error("reset: state not cleared by mid-transaction reset"); end
        aresetn = 1'b1;
        // Present W alone; if AW survived reset the write would fire.
        s_axil_wvalid = 1'b1;
        s_axil_wdata  = 32'hCAFE_F00D;
        s_axil_wstrb  = 4'hF;
        @(negedge aclk);                 // W accepted
        s_axil_wvalid = 1'b0;
        repeat (3) begin
            #1;
            if (!s_axil_bvalid && !s_axil_wready) ok;
            else begin bad; $error("half-write: write fired using an AW held across reset"); end
            @(negedge aclk);
        end
        // Complete the write with a fresh AW to REG1.
        s_axil_awvalid = 1'b1;
        s_axil_awaddr  = 4'h4;
        #1;
        if (s_axil_awready) ok;
        else begin bad; $error("half-write: AWREADY not high with W held"); end
        @(negedge aclk);                 // AW accepted, write fires
        s_axil_awvalid = 1'b0;
        s_axil_bready  = 1'b1;
        #1;
        if (s_axil_bvalid && s_axil_bresp == OKAY) ok;
        else begin bad; $error("half-write: no OKAY response one cycle after AW completed the write"); end
        @(negedge aclk);                 // B taken
        s_axil_bready = 1'b0;
        #1;
        if (!s_axil_bvalid) ok;
        else begin bad; $error("half-write: BVALID not cleared after BREADY"); end
        // Reset values everywhere except the newly written REG1.
        axi_read(4'h0, 0, 0, 32'h0000_0000, OKAY);
        axi_read(4'h4, 0, 0, 32'hCAFE_F00D, OKAY);
        axi_read(4'h8, 0, 0, 32'h0000_0000, OKAY);
        axi_read(4'hC, 0, 0, 32'h0000_0000, OKAY);

        // ---- Done ----
        @(negedge aclk);
        s_axil_awvalid = 1'b0;
        s_axil_wvalid  = 1'b0;
        s_axil_arvalid = 1'b0;
        s_axil_bready  = 1'b0;
        s_axil_rready  = 1'b0;
        repeat (2) @(negedge aclk);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // Watchdog: a hung run ends with a failing verdict.
    initial begin
        #1000000;
        $error("watchdog: simulation did not finish");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
        $finish;
    end

endmodule

`default_nettype wire
